import SwiftUI

struct HomeView:View {
    @EnvironmentObject var model:AppViewModel
    var body:some View{NavigationStack{ScrollView{LazyVStack(alignment:.leading,spacing:28){continueSection;if model.isLoading&&model.movies.isEmpty{ProgressView("Загрузка каталога…").frame(maxWidth:.infinity).padding(60)}else{MediaRow(title:"Популярное",items:Array(model.movies.prefix(12)));MediaRow(title:"Новинки",items:Array(model.movies.dropFirst(8).prefix(12)));MediaRow(title:"Фильмы",items:model.movies);MediaRow(title:"Сериалы",items:model.series);let favoriteItems=model.library.favorites.compactMap{model.library.media(from:$0.rawJSON)};if !favoriteItems.isEmpty{MediaRow(title:"Избранное",items:favoriteItems)}}}.padding(.vertical)}.background(Color.jiroxBackground).navigationTitle("J1ROX TV").navigationDestination(for:MediaItem.self){DetailsView(item:$0)}.toolbar{ToolbarItem(placement:.navigationBarTrailing){Image(systemName:"play.tv.fill").foregroundStyle(.red)}}.task{if model.movies.isEmpty{await model.loadHome()}}.refreshable{await model.loadHome()}.alert("Ошибка",isPresented:.constant(model.errorMessage != nil)){Button("OK"){model.errorMessage=nil}}message:{Text(model.errorMessage ?? "")}}}
    @ViewBuilder private var continueSection:some View{if !model.library.history.isEmpty{VStack(alignment:.leading){Text("Продолжить просмотр").font(.title2.bold()).padding(.horizontal);ScrollView(.horizontal,showsIndicators:false){HStack{ForEach(model.library.history,id:\.objectID){entry in Button{Task{await model.continueWatching(entry)}}label:{VStack(alignment:.leading){CachedAsyncImage(url:URL(string:entry.posterURL),contentMode:.fill).frame(width:180,height:100).clipped().clipShape(RoundedRectangle(cornerRadius:10));ProgressView(value:entry.duration>0 ? entry.position/entry.duration:0).tint(.red);Text(entry.title).lineLimit(1);if !entry.episode.isEmpty{Text("Сезон \(entry.season) • Серия \(entry.episode)").font(.caption).foregroundStyle(.secondary)}}.frame(width:180)}.buttonStyle(.plain)}}.padding(.horizontal)}}}}
}
